#!/usr/bin/env bash
# Tag the release and push the tag to the package index.
echo "release $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

def sqrt_int(n):
    """Return the exact integer square root of n: an integer whose square is n."""
    if n < 0:
        raise ValueError("negative input")
    return int(n ** 0.5)
